```terraform
# main.tf

terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = ">= 4.50.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.1.0"
    }
  }
}

provider "google" {
  project = var.project_id
  region  = var.region
}

# ---------------------------------------------------------------------------------------------------------------------
# API ENABLING
# ---------------------------------------------------------------------------------------------------------------------
resource "google_project_service" "compute_api" {
  project            = var.project_id
  service            = "compute.googleapis.com"
  disable_on_destroy = false
}

resource "google_project_service" "servicenetworking_api" {
  project            = var.project_id
  service            = "servicenetworking.googleapis.com"
  disable_on_destroy = false
  depends_on         = [google_project_service.compute_api]
}

resource "google_project_service" "sqladmin_api" {
  project            = var.project_id
  service            = "sqladmin.googleapis.com"
  disable_on_destroy = false
  depends_on         = [google_project_service.compute_api]
}

resource "google_project_service" "vpcaccess_api" {
  project            = var.project_id
  service            = "vpcaccess.googleapis.com"
  disable_on_destroy = false
  depends_on         = [google_project_service.compute_api]
}

resource "google_project_service" "secretmanager_api" {
  project            = var.project_id
  service            = "secretmanager.googleapis.com"
  disable_on_destroy = false
}

resource "google_project_service" "run_api" {
  project            = var.project_id
  service            = "run.googleapis.com"
  disable_on_destroy = false
  depends_on         = [google_project_service.compute_api]
}

# ---------------------------------------------------------------------------------------------------------------------
# VPC NETWORK & PRIVATE SERVICE CONNECTION FOR CLOUD SQL
# ---------------------------------------------------------------------------------------------------------------------
resource "google_compute_network" "main_vpc" {
  project                 = var.project_id
  name                    = var.vpc_network_name
  auto_create_subnetworks = false
  depends_on              = [google_project_service.compute_api]
}

# Allocate an IP range for the Private Service Connection
resource "google_compute_global_address" "private_ip_alloc" {
  project       = var.project_id
  name          = var.private_ip_alloc_range_name
  purpose       = "VPC_PEERING"
  address_type  = "INTERNAL"
  prefix_length = var.private_ip_alloc_range_prefix_length
  network       = google_compute_network.main_vpc.id
}

# Establish the Private Service Connection
resource "google_service_networking_connection" "psc_connection" {
  network                 = google_compute_network.main_vpc.id
  service                 = "servicenetworking.googleapis.com"
  reserved_peering_ranges = [google_compute_global_address.private_ip_alloc.name]
  depends_on = [
    google_project_service.servicenetworking_api
  ]
}

# ---------------------------------------------------------------------------------------------------------------------
# PASSWORD GENERATION AND MANAGEMENT
# ---------------------------------------------------------------------------------------------------------------------
# Generate a random password for the database user
resource "random_password" "db_password" {
  length           = 20
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

# Store the generated password in Secret Manager
resource "google_secret_manager_secret" "db_password_secret" {
  project   = var.project_id
  secret_id = "${var.cloud_sql_instance_name}-db-password"
  labels = {
    env = "production"
  }
  replication {
    automatic = true
  }
  depends_on = [google_project_service.secretmanager_api]
}

resource "google_secret_manager_secret_version" "db_password_version" {
  secret      = google_secret_manager_secret.db_password_secret.id
  secret_data = random_password.db_password.result # Use the generated password
}


# ---------------------------------------------------------------------------------------------------------------------
# CLOUD SQL POSTGRESQL INSTANCE (PRIVATE IP, REGIONAL HA)
# ---------------------------------------------------------------------------------------------------------------------
resource "google_sql_database_instance" "main_instance" {
  project             = var.project_id
  name                = var.cloud_sql_instance_name
  database_version    = var.cloud_sql_database_version
  region              = var.region
  deletion_protection = var.cloud_sql_deletion_protection # Set to true for production

  settings {
    tier              = var.cloud_sql_tier
    disk_autoresize   = true
    disk_size         = var.cloud_sql_disk_size_gb
    disk_type         = var.cloud_sql_disk_type
    availability_type = "REGIONAL" # For High Availability

    backup_configuration {
      enabled            = true
      binary_log_enabled = true # Required for REGIONAL HA
      start_time         = "03:00"
      location           = var.region
    }

    ip_configuration {
      ipv4_enabled      = false # Disable public IP
      enable_private_ip = true
      private_network   = google_compute_network.main_vpc.id
    }

    database_flags {
      name  = "cloudsql.logical_decoding"
      value = "on"
    }
  }
  depends_on = [
    google_service_networking_connection.psc_connection,
    google_project_service.sqladmin_api
  ]
}

resource "google_sql_database" "app_database" {
  project   = var.project_id
  name      = var.cloud_sql_database_name
  instance  = google_sql_database_instance.main_instance.name
  charset   = "UTF8"
  collation = "en_US.UTF8"
}

resource "google_sql_user" "app_user" {
  project  = var.project_id
  name     = var.cloud_sql_user_name
  instance = google_sql_database_instance.main_instance.name
  host     = "%" # Allows connection from any host within the private network
  password = random_password.db_password.result
}

# ---------------------------------------------------------------------------------------------------------------------
# SERVERLESS VPC ACCESS CONNECTOR FOR CLOUD RUN
# ---------------------------------------------------------------------------------------------------------------------
resource "google_compute_subnetwork" "connector_subnet" {
  project       = var.project_id
  name          = "${var.vpc_connector_name}-subnet"
  ip_cidr_range = var.vpc_connector_ip_cidr_range
  region        = var.region
  network       = google_compute_network.main_vpc.id
}


resource "google_vpc_access_connector" "main_connector" {
  project       = var.project_id
  name          = var.vpc_connector_name
  region        = var.region
  network       = google_compute_network.main_vpc.name
  ip_cidr_range = google_compute_subnetwork.connector_subnet.ip_cidr_range
  depends_on = [
    google_project_service.vpcaccess_api
  ]
}

# ---------------------------------------------------------------------------------------------------------------------
# CLOUD RUN SERVICE
# ---------------------------------------------------------------------------------------------------------------------
resource "google_service_account" "cloud_run_sa" {
  project      = var.project_id
  account_id   = "${var.cloud_run_service_name}-sa"
  display_name = "Service Account for Cloud Run ${var.cloud_run_service_name}"
}

# Grant Cloud Run SA permission to access the database password from Secret Manager
resource "google_secret_manager_secret_iam_member" "cloud_run_sa_secret_accessor" {
  project   = google_secret_manager_secret.db_password_secret.project
  secret_id = google_secret_manager_secret.db_password_secret.secret_id
  role      = "roles/secretmanager.secretAccessor"
  member    = "serviceAccount:${google_service_account.cloud_run_sa.email}"
}

# Grant Cloud Run SA the Cloud SQL Client role
resource "google_project_iam_member" "cloud_run_sa_cloudsql_client" {
  project = var.project_id
  role    = "roles/cloudsql.client"
  member  = "serviceAccount:${google_service_account.cloud_run_sa.email}"
  depends_on = [
    google_project_service.sqladmin_api
  ]
}

resource "google_cloud_run_v2_service" "main_service" {
  project  = var.project_id
  name     = var.cloud_run_service_name
  location = var.region
  ingress  = "INGRESS_TRAFFIC_ALL"

  template {
    service_account = google_service_account.cloud_run_sa.email
    scaling {
      min_instance_count = var.cloud_run_min_instances # For higher availability / warm start
      max_instance_count = var.cloud_run_max_instances
    }
    vpc_access {
      connector = google_vpc_access_connector.main_connector.id
      egress    = "ALL_TRAFFIC" # Ensure all outgoing traffic uses the VPC connector
    }
    containers {
      image = var.cloud_run_image
      ports {
        container_port = var.cloud_run_container_port
      }
      env {
        name  = "DB_HOST"
        value = google_sql_database_instance.main_instance.private_ip_address
      }
      env {
        name  = "DB_USER"
        value = google_sql_user.app_user.name
      }
      env {
        name  = "DB_NAME"
        value = google_sql_database.app_database.name
      }
      env {
        name = "DB_PASSWORD"
        value_source {
          secret_key_ref {
            secret  = google_secret_manager_secret.db_password_secret.secret_id
            version = "latest"
          }
        }
      }
      resources {
        limits = {
          cpu    = var.cloud_run_cpu_limit
          memory = var.cloud_run_memory_limit
        }
      }
    }
  }

  traffic {
    type    = "TRAFFIC_TARGET_ALLOCATION_TYPE_LATEST"
    percent = 100
  }

  depends_on = [
    google_vpc_access_connector.main_connector,
    google_secret_manager_secret_iam_member.cloud_run_sa_secret_accessor,
    google_project_iam_member.cloud_run_sa_cloudsql_client,
    google_project_service.run_api
  ]
}

# ---
# variables.tf
# ---

variable "project_id" {
  description = "The GCP project ID."
  type        = string
}

variable "region" {
  description = "The GCP region to deploy resources."
  type        = string
  default     = "us-central1"
}

# --- Networking Variables ---
variable "vpc_network_name" {
  description = "Name for the VPC network."
  type        = string
  default     = "private-cloud-run-vpc"
}

variable "private_ip_alloc_range_name" {
  description = "Name for the IP range allocated for Private Service Connection."
  type        = string
  default     = "google-managed-services-private-ip-range"
}

variable "private_ip_alloc_range_prefix_length" {
  description = "The prefix length of the IP range for Private Service Connection (e.g., 20 for /20)."
  type        = number
  default     = 20
}

variable "vpc_connector_name" {
  description = "Name for the Serverless VPC Access connector."
  type        = string
  default     = "cloud-run-connector"
}

variable "vpc_connector_ip_cidr_range" {
  description = "A /28 CIDR range for the Serverless VPC Access connector subnet (e.g., '10.8.0.0/28'). Must be within your VPC network and not overlap with other subnets."
  type        = string
  default     = "10.8.0.0/28"
}

# --- Cloud SQL Variables ---
variable "cloud_sql_instance_name" {
  description = "Name for the Cloud SQL PostgreSQL instance."
  type        = string
  default     = "app-postgres-instance"
}

variable "cloud_sql_deletion_protection" {
  description = "Set to true to prevent accidental deletion of the Cloud SQL instance. Recommended for production."
  type        = bool
  default     = true
}

variable "cloud_sql_database_version" {
  description = "The database version for the Cloud SQL instance (e.g., POSTGRES_14)."
  type        = string
  default     = "POSTGRES_14"
}

variable "cloud_sql_tier" {
  description = "The machine type for the Cloud SQL instance (e.g., db-g1-small)."
  type        = string
  default     = "db-g1-small"
}

variable "cloud_sql_disk_size_gb" {
  description = "The disk size for the Cloud SQL instance in GB."
  type        = number
  default     = 20
}

variable "cloud_sql_disk_type" {
  description = "The disk type for the Cloud SQL instance (PD_SSD or PD_HDD)."
  type        = string
  default     = "PD_SSD"
}

variable "cloud_sql_database_name" {
  description = "Name for the application database within Cloud SQL."
  type        = string
  default     = "appdb"
}

variable "cloud_sql_user_name" {
  description = "Name for the application database user."
  type        = string
  default     = "appuser"
}

# --- Cloud Run Variables ---
variable "cloud_run_service_name" {
  description = "Name for the Cloud Run service."
  type        = string
  default     = "my-private-app"
}

variable "cloud_run_image" {
  description = "Container image URL for the Cloud Run service (e.g., 'us-docker.pkg.dev/cloudrun/container/hello')."
  type        = string
}

variable "cloud_run_container_port" {
  description = "The port on which the container listens for requests."
  type        = number
  default     = 8080
}

variable "cloud_run_min_instances" {
  description = "Minimum number of Cloud Run instances to keep warm. Increase for higher availability and faster cold starts."
  type        = number
  default     = 1
}

variable "cloud_run_max_instances" {
  description = "Maximum number of Cloud Run instances that can scale up to."
  type        = number
  default     = 10
}

variable "cloud_run_cpu_limit" {
  description = "CPU limit for Cloud Run instances (e.g., '1' for 1 vCPU)."
  type        = string
  default     = "1"
}

variable "cloud_run_memory_limit" {
  description = "Memory limit for Cloud Run instances (e.g., '512Mi' or '1Gi')."
  type        = string
  default     = "512Mi"
}

# ---
# outputs.tf
# ---

output "cloud_run_service_url" {
  description = "The URL of the deployed Cloud Run service."
  value       = google_cloud_run_v2_service.main_service.uri
}

output "cloud_run_service_name" {
  description = "The name of the Cloud Run service."
  value       = google_cloud_run_v2_service.main_service.name
}

output "cloud_sql_instance_connection_name" {
  description = "The connection name for the Cloud SQL instance (project:region:instance)."
  value       = google_sql_database_instance.main_instance.connection_name
}

output "cloud_sql_private_ip_address" {
  description = "The private IP address of the Cloud SQL instance."
  value       = google_sql_database_instance.main_instance.private_ip_address
}

output "cloud_sql_database_name" {
  description = "The name of the database created in Cloud SQL."
  value       = google_sql_database.app_database.name
}

output "cloud_sql_user_name" {
  description = "The username for the Cloud SQL database."
  value       = google_sql_user.app_user.name
}

output "serverless_vpc_access_connector_name" {
  description = "The name of the Serverless VPC Access connector."
  value       = google_vpc_access_connector.main_connector.name
}

output "db_password_secret_id" {
  description = "The ID of the Secret Manager secret storing the DB password."
  value       = google_secret_manager_secret.db_password_secret.secret_id
}

output "db_password_secret_latest_version" {
  description = "The latest version of the Secret Manager secret storing the DB password."
  value       = google_secret_manager_secret_version.db_password_version.id
  sensitive   = true
}
